use vstd::prelude::*;

verus! {

spec fn seq_rev<A>(s: Seq<A>) -> Seq<A> {
    s.reverse()
}

fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
    ensures
        rev@ == seq_rev(s@),
        rev@.len() == s@.len(),
{
    let n = s.len();
    let mut rev: Vec<i8> = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            n == s@.len(),
            rev@.len() + i + 1 == n,
            // rev is the reverse of the suffix s[i+1 .. n)
            rev@ == seq_rev(s@.subrange((i + 1) as int, n as int)),
        decreases i + 1,
    {
        rev.push(s[i]);

        assert(rev@.len() + i == n);
        // After pushing s[i], rev becomes reverse of s[i .. n)
        assert(rev@ == seq_rev(s@.subrange(i as int, n as int)));
    }

    // At loop end, i == 0 has been processed, so rev is reverse of s[0..n)
    assert(rev@ == seq_rev(s@.subrange(0, n as int)));
    rev
}

}

